with t as (select $j${"Kid Massage": {"ko": "3살 이상 아이를 위한 부드러운 마사지예요. 예민한 아이 피부에 맞춰 코코넛 오일을 써요.\n진행은 이렇게 돼요: 상담 · 건강 체크 → 따뜻한 약초 족욕 → 마사지 → 가벼운 간식\n원하면 마사지 전에 스팀 사우나도 할 수 있어요. 부모님과 같은 방 이용은 상담 때 확인해 드려요.", "en": "A gentle massage for children aged 3 and up, using coconut oil suited to sensitive skin.\nHow it goes: consultation & health check → warm herbal foot soak → massage → light snack\nAn optional steam bath is available before the massage. We'll check same-room options with parents when you book.", "vi": "Massage nhẹ nhàng cho bé từ 3 tuổi, dùng dầu dừa hợp với làn da nhạy cảm.\nQuy trình: tư vấn & kiểm tra sức khỏe → ngâm chân thảo dược ấm → massage → ăn nhẹ\nCó thể xông hơi trước khi massage. Việc ở cùng phòng với bố mẹ sẽ được xác nhận khi đặt lịch."}, "Swedish Massage": {"ko": "오일을 바르고 길게 쓸어 주고 주물러 풀어 주는 기본 전신 마사지예요.\n세기가 부드러운 편이라 마사지가 처음이거나 여행 첫날 피로를 풀고 싶을 때 잘 맞아요.", "en": "A classic full-body oil massage with long gliding and kneading strokes.\nThe pressure is on the gentle side, so it suits first-timers or a first-day-of-the-trip reset.", "vi": "Massage toàn thân cơ bản với dầu, vuốt dài và xoa bóp.\nLực nhẹ nhàng, hợp với người mới massage lần đầu hoặc muốn thư giãn ngày đầu chuyến đi."}, "Aroma Massage": {"ko": "천연 에센셜 오일을 쓰는 마사지예요. 문지르고 눌러 주는 동작으로 향이 깊이 스며들게 해요.\n몸보다 마음이 지쳤을 때, 푹 쉬고 싶은 날에 추천해요.", "en": "Massage with natural essential oils, using rubbing and pressing strokes so the scent sinks in.\nGood for days when your mind is more tired than your body.", "vi": "Massage với tinh dầu thiên nhiên, động tác xoa và miết giúp hương thơm thấm sâu.\nHợp với những ngày cần thư giãn tinh thần."}, "Deep Massage": {"ko": "지압점을 눌러 주면서 근육 깊은 곳까지 밀어 풀어 주는 마사지예요.\n뭉치고 굳은 어깨 · 허리처럼 아픈 곳이 있을 때 좋아요. 세게 받는 편이라 아프면 바로 말해 주세요.", "en": "Acupressure combined with deep strokes into the muscle.\nGood for stiff shoulders or a sore back. The pressure is firm, so tell your therapist if it's too strong.", "vi": "Kết hợp bấm huyệt và miết sâu vào cơ.\nHợp khi bị cứng vai, đau lưng. Lực khá mạnh, hãy báo kỹ thuật viên nếu thấy đau."}, "Herbal Massage": {"ko": "따뜻하게 데운 약초 주머니로 몸을 눌러 가며 하는 마사지예요. 주머니에는 생강 · 레몬그라스 · 감초 같은 약초가 들어가요.\n몸을 데워 순환을 돕고, 피로가 쌓였을 때 좋아요.", "en": "Massage with warm herbal compress balls filled with herbs like ginger, lemongrass and licorice.\nIt warms the body and helps circulation when you're worn out.", "vi": "Massage bằng túi thảo dược ấm (gừng, sả, cam thảo…).\nLàm ấm cơ thể, giúp lưu thông máu khi mệt mỏi."}, "Hot-Stone Massage": {"ko": "따뜻하게 데운 돌을 몸 위에 올리고 문질러 주는 마사지예요.\n돌의 열이 근육 깊은 곳까지 전해져 몸이 금방 따뜻해지고 긴장이 풀려요. 에어컨에 몸이 차가워졌을 때 좋아요.", "en": "Heated stones are placed and glided over your body.\nThe warmth reaches deep into the muscles and helps you relax — nice after a day in air-conditioning.", "vi": "Đá được làm nóng đặt và miết lên cơ thể.\nHơi ấm thấm sâu vào cơ, giúp thư giãn nhanh — rất hợp sau một ngày ở phòng máy lạnh."}, "Hot-Stone Massage With Herbal": {"ko": "핫스톤과 약초 주머니를 한 번에 받는 마사지예요.\n둘 중에 고르기 어렵다면 이걸로 두 가지를 다 느껴 보세요.", "en": "Hot stones and herbal compresses in one session.\nCan't choose between the two? Try both at once.", "vi": "Kết hợp đá nóng và túi thảo dược trong một liệu trình.\nKhông chọn được thì thử cả hai."}, "Pregnancy Massage": {"ko": "임신 중 몸 상태에 맞춘 마사지예요. 긴장과 스트레스를 덜고, 다리 쥐가 나는 것을 줄이는 데 도움을 줘요.\n촉촉한 오일로 예민해진 피부도 함께 챙겨요. 임신 주수는 예약할 때 알려 주세요.", "en": "A massage adapted for pregnancy — eases tension and stress and helps with leg cramps.\nA moisturising oil cares for sensitive skin. Please tell us how many weeks along you are when booking.", "vi": "Massage dành cho mẹ bầu — giảm căng thẳng, giảm chuột rút.\nDầu dưỡng ẩm chăm sóc làn da nhạy cảm. Vui lòng cho biết tuần thai khi đặt lịch."}, "Traditional Vietnamese Massage": {"ko": "로션을 바르고 굴리기 · 누르기 · 지압을 섞어 하는 베트남식 마사지예요.\n뭉친 근육을 풀고 순환을 돕는 데 좋아요. 베트남에 왔으니 한 번은 받아 볼 만해요.", "en": "Vietnamese-style massage with lotion — rolling, pressing and acupressure.\nGreat for knotted muscles and circulation. Worth trying once while you're in Vietnam.", "vi": "Massage kiểu Việt Nam với lotion — lăn, chặt, day ấn huyệt.\nGiảm căng cơ, tăng lưu thông máu."}, "Thai Massage": {"ko": "오일 없이 지압과 스트레칭을 섞어 하는 타이식 마사지예요. 관절을 부드럽게 늘려 줘요.\n몸이 뻣뻣하거나 오래 걸어 다닌 날에 좋아요.", "en": "Oil-free Thai massage mixing acupressure with gentle stretches and joint movement.\nGreat when you feel stiff or after a long day of walking.", "vi": "Massage Thái không dùng dầu, kết hợp bấm huyệt và kéo giãn nhẹ.\nHợp khi người cứng mỏi hoặc sau một ngày đi bộ nhiều."}, "Bamboo Massage": {"ko": "손 대신 따뜻하게 데운 대나무 통을 여러 방향으로 굴려 풀어 주는 마사지예요.\n넓은 면으로 고르게 눌러 줘서 시원하면서도 부드러워요.", "en": "Instead of hands, a warmed bamboo tube is rolled over the body in many directions.\nThe wide surface gives even, satisfying pressure.", "vi": "Dùng ống tre được làm ấm lăn theo nhiều hướng thay cho tay.\nLực đều, vừa đã vừa êm."}, "Cactus Massage": {"ko": "선인장 진액을 써서 하는 마사지예요. 피부가 매끄럽고 시원해져요.\n햇볕에 타서 피부가 화끈거릴 때 특히 좋아요.", "en": "Massage using cactus sap, leaving skin smooth and cool.\nEspecially soothing for sunburned skin.", "vi": "Massage bằng nhựa xương rồng, giúp da mịn và mát.\nĐặc biệt dễ chịu cho da bị cháy nắng."}, "Clover Spa Massage": {"ko": "클로버 스파에서만 받을 수 있는 대표 마사지예요. 바다달팽이(소라) 껍데기와 약초를 함께 써요.\n천천히 깊게 눌러 주는 동작으로 쑤시고 뭉친 곳을 풀고 몸을 따뜻하게 해 줘요. 클로버에 왔다면 한 번은 받아 볼 만해요.", "en": "Clover Spa's signature, only available here — sea snail shells and herbs together.\nSlow, deep strokes ease aches and stiffness and warm you up.", "vi": "Dịch vụ đặc trưng chỉ có tại Clover Spa — kết hợp ốc và thảo dược.\nĐộng tác chậm, sâu giúp giảm đau mỏi và làm ấm cơ thể."}, "Foot Reflexology + Hot Stone": {"ko": "발바닥 반사구를 지압하고 따뜻한 돌로 풀어 주는 발 마사지예요.\n하루 종일 걸어 다녀 발이 붓고 무거울 때 좋아요.", "en": "Foot reflexology on pressure points plus warm stones.\nPerfect when your feet are swollen and heavy after walking all day.", "vi": "Bấm huyệt phản xạ bàn chân kết hợp đá nóng.\nHợp khi chân mỏi, sưng sau một ngày đi nhiều."}, "Foot Lover Therapy": {"ko": "클로버의 대표 발 마사지예요. 핫스톤 발 지압에 발 각질 관리까지 함께 해 줘요.\n발이 피곤하면서 뒤꿈치도 거칠 때 한 번에 해결돼요.", "en": "Clover's signature foot treatment — hot-stone foot acupressure plus a foot scrub.\nTired feet and rough heels, sorted in one go.", "vi": "Liệu trình chân đặc trưng — bấm huyệt chân với đá nóng kèm tẩy tế bào chết chân."}, "Natural Facial": {"ko": "깨끗하게 딥 클렌징한 뒤 천연 재료 영양 팩을 올려 주는 얼굴 관리예요.\n햇볕과 에어컨에 건조해진 피부에 수분을 채워 줘요.", "en": "Deep cleansing followed by a natural nutrient mask.\nRehydrates skin dried out by sun and air-conditioning.", "vi": "Làm sạch sâu rồi đắp mặt nạ dưỡng chất thiên nhiên.\nCấp ẩm cho da khô do nắng và máy lạnh."}, "Brilliant Whitening Facial": {"ko": "톤을 밝혀 주는 얼굴 관리예요. 기미 · 잡티 쪽을 고급 세럼으로 관리하고 피부를 촉촉하게 정리해요.", "en": "A brightening facial — premium serum care for dark spots, leaving skin even and moist.", "vi": "Chăm sóc làm sáng da — serum cao cấp cho nám, đốm nâu, giúp da đều màu và ẩm mịn."}, "Pushed Vitamin C Facial": {"ko": "클렌징 → 얼굴 마사지 → 비타민C 팩 순서로 진행돼요.\n칙칙해진 피부 톤과 탄력을 함께 챙기고 싶을 때 좋아요.", "en": "Cleansing → relaxing facial massage → vitamin C mask.\nGood for dull skin tone and firmness.", "vi": "Làm sạch → massage mặt thư giãn → mặt nạ vitamin C.\nHợp với da xỉn màu, cần săn chắc."}}$j$::jsonb as d)
update public.shops s
   set data = jsonb_set(s.data, '{menu}', (
         select jsonb_agg(case when t.d ? (m->'name'->>'en') then m || jsonb_build_object('more', t.d->(m->'name'->>'en')) else m end order by o)
           from jsonb_array_elements(s.data->'menu') with ordinality x(m, o), t))
 where s.id = 'clover-spa' and jsonb_typeof(s.data->'menu') = 'array';

-- 확인: 자세히 보기가 붙은 메뉴 수
select id, jsonb_array_length(data->'menu') as menus,
       (select count(*) from jsonb_array_elements(data->'menu') m where m ? 'more') as with_more
  from public.shops where id = 'clover-spa';
